CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname='kost_app') THEN CREATE ROLE kost_app LOGIN PASSWORD 'local-app-only' NOSUPERUSER NOCREATEDB NOCREATEROLE NOBYPASSRLS; END IF; END $$;
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL CHECK(email=lower(email)),password_hash text NOT NULL,verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),csrf_token text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),last_seen_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,revoked_at timestamptz);
CREATE TABLE verification_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('verify','reset')),expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE TABLE organizations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),user_id uuid NOT NULL REFERENCES users(id),role text NOT NULL CHECK(role IN ('Owner','Manager','Finance','Operations')),revoked_at timestamptz,UNIQUE(organization_id,user_id),UNIQUE(organization_id,id));
CREATE TABLE properties(id uuid DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,city text NOT NULL,timezone text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(id),UNIQUE(organization_id,id));
CREATE TABLE location_access(organization_id uuid NOT NULL,membership_id uuid NOT NULL,property_id uuid NOT NULL,PRIMARY KEY(organization_id,membership_id,property_id),FOREIGN KEY(organization_id,membership_id) REFERENCES memberships(organization_id,id),FOREIGN KEY(organization_id,property_id) REFERENCES properties(organization_id,id));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,object_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE email_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),kind text NOT NULL CHECK(kind IN ('verify','reset')),token_hash text NOT NULL REFERENCES verification_tokens(token_hash),secret_token text,available_at timestamptz NOT NULL DEFAULT now(),attempts integer NOT NULL DEFAULT 0,sent_at timestamptz,failed_at timestamptz);
CREATE INDEX pending_email ON email_outbox(available_at) WHERE sent_at IS NULL AND failed_at IS NULL;
CREATE FUNCTION current_actor() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.actor_id',true),'')::uuid $$;
CREATE FUNCTION current_org() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.organization_id',true),'')::uuid $$;
ALTER TABLE memberships ENABLE ROW LEVEL SECURITY; ALTER TABLE memberships FORCE ROW LEVEL SECURITY;
CREATE POLICY membership_scope ON memberships USING(user_id=current_actor());
CREATE POLICY membership_create ON memberships FOR INSERT WITH CHECK(user_id=current_actor() AND role='Owner' AND organization_id=current_org());
ALTER TABLE organizations ENABLE ROW LEVEL SECURITY; ALTER TABLE organizations FORCE ROW LEVEL SECURITY;
CREATE POLICY org_read ON organizations FOR SELECT USING(EXISTS(SELECT FROM memberships m WHERE m.organization_id=id AND m.user_id=current_actor() AND revoked_at IS NULL));
CREATE POLICY org_create ON organizations FOR INSERT WITH CHECK(id=current_org() AND current_actor() IS NOT NULL);
CREATE FUNCTION can_access_location(org uuid,location uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT FROM memberships m WHERE m.organization_id=org AND m.user_id=current_actor() AND m.revoked_at IS NULL AND (m.role='Owner' OR EXISTS(SELECT FROM location_access a WHERE a.organization_id=org AND a.membership_id=m.id AND a.property_id=location))) $$;
ALTER TABLE location_access ENABLE ROW LEVEL SECURITY; ALTER TABLE location_access FORCE ROW LEVEL SECURITY;
CREATE POLICY access_read ON location_access USING(organization_id=current_org() AND EXISTS(SELECT FROM memberships m WHERE m.id=membership_id AND m.user_id=current_actor() AND m.revoked_at IS NULL));
ALTER TABLE properties ENABLE ROW LEVEL SECURITY; ALTER TABLE properties FORCE ROW LEVEL SECURITY;
CREATE POLICY property_read ON properties FOR SELECT USING(organization_id=current_org() AND can_access_location(organization_id,id));
CREATE POLICY property_create ON properties FOR INSERT WITH CHECK(organization_id=current_org() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=properties.organization_id AND m.user_id=current_actor() AND m.role='Owner' AND m.revoked_at IS NULL));
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY; ALTER TABLE audit_logs FORCE ROW LEVEL SECURITY;
CREATE POLICY audit_insert ON audit_logs FOR INSERT WITH CHECK(organization_id=current_org() AND actor_id=current_actor() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=audit_logs.organization_id AND m.revoked_at IS NULL));
CREATE POLICY audit_read ON audit_logs FOR SELECT USING(organization_id=current_org() AND EXISTS(SELECT FROM memberships m WHERE m.organization_id=audit_logs.organization_id AND m.role='Owner' AND m.revoked_at IS NULL));
GRANT USAGE ON SCHEMA public TO kost_app;
GRANT SELECT,INSERT ON organizations,memberships,properties,audit_logs TO kost_app;
GRANT SELECT ON location_access TO kost_app;
GRANT SELECT,INSERT,UPDATE ON users,sessions,verification_tokens,email_outbox TO kost_app;
